import { memo } from "react";
import { useLocale, useTranslations } from "next-intl";
import { PlainSummary as PlainSummaryData } from "../../types/proposal.types";

interface PlainSummaryProps {
  summary?: PlainSummaryData | null;
  /** Official BOCG PDF the summary was written from */
  sourceUrl?: string | null;
}

/** Plain-language explanation of a vote, generated by AI from the official initiative text. */
const PlainSummaryComponent = ({ summary, sourceUrl }: PlainSummaryProps) => {
  const t = useTranslations("votecard-component");
  const locale = useLocale();
  const text = summary?.[locale] ?? summary?.es;

  if (!text) return null;

  return (
    <section className="flex flex-col gap-2 rounded-md border-l-4 border-drPurple bg-drlight px-4 py-3 font-drsans text-sm">
      <p className="font-bold">{t("summary-title")}</p>
      <p>{text.summary}</p>
      <p>
        <span className="font-bold">{t("yes-means")} </span>
        {text.yes_means}
      </p>
      <p>
        <span className="font-bold">{t("no-means")} </span>
        {text.no_means}
      </p>
      <p className="text-xs text-drgray">
        {t("ai-disclaimer")}
        {sourceUrl && (
          <>
            {" "}
            <a href={sourceUrl} target="_blank" rel="noopener noreferrer" className="underline" onClick={(e) => e.stopPropagation()}>
              {t("official-text")}
            </a>
          </>
        )}
      </p>
    </section>
  );
};

export const PlainSummary = memo(PlainSummaryComponent);
